function validate([events]) {
  if (events.length < 1 || events.length > 1000) return 'events needs 1 to 1000 presses.';
  for (let i = 0; i < events.length; i++) {
    const press = events[i];
    if (press.length !== 2) return 'Each event is [index, time].';
    if (press[0] < 1 || press[0] > 100000 || press[1] < 1 || press[1] > 100000) return 'Button indices and times are between 1 and 10^5.';
    if (i > 0 && press[1] <= events[i - 1][1]) return 'Times must strictly increase along events.';
  }
  return null;
}

