function buttonWithLongestTime(events) {
  let bestIndex = events[0][0];
  let longest = events[0][1];
  for (let i = 1; i < events.length; i++) {
    const [index, time] = events[i];
    const duration = time - events[i - 1][1];
    if (duration > longest || (duration === longest && index < bestIndex)) {
      longest = duration;
      bestIndex = index;
    }
  }
  return bestIndex;
}

