function buttonWithLongestTime(events) {
  const durations = events.map(([, time], i) => (i === 0 ? time : time - events[i - 1][1]));
  const longest = Math.max(...durations);
  const tied = events.filter((_, i) => durations[i] === longest).map(([index]) => index);
  return Math.min(...tied);
}

