function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  // Small inputs use few buttons and short gaps, so repeated buttons and tied durations are common.
  const buttons = size === 'large' ? 100000 : 1 + Math.floor(rand() * 6);
  const gap = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const events = [];
  let time = 0;
  for (let i = 0; i < n; i++) {
    time += 1 + Math.floor(rand() * gap);
    events.push([1 + Math.floor(rand() * buttons), time]);
  }
  return [events];
}
